# Significance of the pairwise category difference in Tables 5–7.
sig &lt;- data.frame(
  variable = character(), field = character(), route = character(),
  stars = character(), stringsAsFactors = FALSE
)

add_sig &lt;- function(variable, field, stars) {
  data.frame(
    variable = variable,
    field = rep(field, 4),
    route = c("Dropout trajectory", "Slow progression",
              "Successful recovery", "Optimal route"),
    stars = stars,
    stringsAsFactors = FALSE
  )
}

sig &lt;- rbind(
  sig,
  add_sig("Parental education", "Arts & Humanities", c("n.s.","n.s.","n.s.","*")),
  add_sig("Parental education", "Social & Law", c("*","n.s.","***","***")),
  add_sig("Parental education", "Health", c("*","*","**","***")),
  add_sig("Parental education", "Sciences", c("n.s.","n.s.","n.s.","n.s.")),
  add_sig("Parental education", "Engineering & Architecture", c("*","n.s.","***","**")),

  add_sig("Gender", "Arts & Humanities", c("n.s.","n.s.","n.s.","n.s.")),
  add_sig("Gender", "Social & Law", c("***","***","***","***")),
  add_sig("Gender", "Health", c("n.s.","*","***","***")),
  add_sig("Gender", "Sciences", c("***","***","n.s.","***")),
  add_sig("Gender", "Engineering & Architecture", c("***","**","n.s.","***")),

