    key = "dropout",
    min = .03,
    max = .16,
    colour = "#527CA5"
  )
)

# ============================================================
# SVG: two gender rows, Native vs Non-native on each row
# ============================================================

panel_svg &lt;- function(d, outcome_name) {

  meta &lt;- outcome_meta[[outcome_name]]

  W &lt;- 320
  H &lt;- 205

  x0 &lt;- 78
  x1 &lt;- 278

  y_f &lt;- 72
  y_m &lt;- 145

  xmap &lt;- function(v) {
    x0 + (v - meta$min) / (meta$max - meta$min) * (x1 - x0)
  }

  getv &lt;- function(g, b) {
    d[d$gender == g & d$background == b, meta$key]
  }

  fn &lt;- getv("Female", "Native")
  fz &lt;- getv("Female", "Non-native")
  mn &lt;- getv("Male", "Native")
  mz &lt;- getv("Male", "Non-native")

  x_fn &lt;- xmap(fn)
  x_fz &lt;- xmap(fz)
  x_mn &lt;- xmap(mn)
  x_mz &lt;- xmap(mz)

  gap_f &lt;- 100 * (fn - fz)
  gap_m &lt;- 100 * (mn - mz)

  row_svg &lt;- function(y, label, xn, xz, vn, vz, gap) {

    paste0(
      # gender label
      '&lt;text x="8" y="', y+4,
      '" font-size="11" font-weight="700" fill="#444"&gt;',
      label, '&lt;/text&gt;',

      # row scale
      '&lt;line x1="', x0, '" y1="', y,
      '" x2="', x1, '" y2="', y,
      '" stroke="#dddddd" stroke-width="2" stroke-linecap="round"/&gt;',

      # connector
      '&lt;line x1="', min(xn,xz), '" y1="', y,
      '" x2="', max(xn,xz), '" y2="', y,
      '" stroke="', meta$colour,
      '" stroke-width="5" stroke-linecap="round" opacity=".32"/&gt;',

      # Native = solid
      '&lt;circle cx="', xn, '" cy="', y,
      '" r="7.5" fill="', meta$colour,
      '" stroke="#fff" stroke-width="1.8"/&gt;',

      # Non-native = open
      '&lt;circle cx="', xz, '" cy="', y,
      '" r="7" fill="#fff" stroke="', meta$colour,
      '" stroke-width="2.5"/&gt;',

      # Values
      '&lt;text x="', xn, '" y="', y-15,
      '" text-anchor="middle" font-size="10.5" font-weight="700" fill="#333"&gt;',
      sprintf("%.1f%%",100*vn), '&lt;/text&gt;',

      '&lt;text x="', xz, '" y="', y+24,
      '" text-anchor="middle" font-size="10.5" font-weight="700" fill="#555"&gt;',
      sprintf("%.1f%%",100*vz), '&lt;/text&gt;',

      # gap on far right
      '&lt;text x="310" y="', y+4,
      '" text-anchor="end" font-size="9" font-weight="700" fill="#777"&gt;',
      'Δ ', sprintf("%.1f",gap), '&lt;/text&gt;'
    )
  }

  HTML(
    paste0(
      '&lt;svg viewBox="0 0 ',W,' ',H,
      '" style="width:100%;height:auto;display:block;"&gt;',

      # top labels / legend integrated
      '&lt;circle cx="83" cy="18" r="5" fill="', meta$colour, '"/&gt;',
      '&lt;text x="94" y="22" font-size="9.5" fill="#666"&gt;Native&lt;/text&gt;',

      '&lt;circle cx="145" cy="18" r="5" fill="#fff" stroke="', meta$colour, '" stroke-width="2"/&gt;',
      '&lt;text x="156" y="22" font-size="9.5" fill="#666"&gt;Non-native&lt;/text&gt;',

      '&lt;text x="310" y="22" text-anchor="end" font-size="8.5" fill="#888"&gt;Δ Native − Non-native&lt;/text&gt;',

      # rows
      row_svg(y_f, "Female", x_fn, x_fz, fn, fz, gap_f),
      row_svg(y_m, "Male", x_mn, x_mz, mn, mz, gap_m),

      # faint separator
      '&lt;line x1="8" y1="108" x2="310" y2="108" stroke="#f0f0f0" stroke-width="1"/&gt;',

      # shared local scale
      '&lt;text x="',x0,'" y="197" text-anchor="start" font-size="8.5" fill="#999"&gt;',
      sprintf("%.0f%%",100*meta$min), '&lt;/text&gt;',
      '&lt;text x="',x1,'" y="197" text-anchor="end" font-size="8.5" fill="#999"&gt;',
      sprintf("%.0f%%",100*meta$max), '&lt;/text&gt;',

      '&lt;/svg&gt;'
    )
  )
}

