    div(
      class = "source-note",
      HTML(
        "&lt;strong&gt;How to read this:&lt;/strong&gt; each school-context panel has two rows, one for women and one for men. Within each row, the filled point is Native and the open point is Non-native. The horizontal distance between the two points is the migrant-background gap; comparing the two rows shows gender differences. All three panels use the same outcome-specific scale.&lt;br&gt;
        &lt;strong&gt;Source:&lt;/strong&gt; Sánchez-Gelabert, A., Elias Andreu, M. & Bouvier, N. (2024).
        &lt;em&gt;Transition to post-compulsory education according to migrant background and gender in Catalonia:
        Exploring the effect of non-native student concentration&lt;/em&gt;.
        International Journal of Educational Research, 124, 102321.
        &lt;a href='https://doi.org/10.1016/j.ijer.2024.102321' target='_blank'&gt;DOI&lt;/a&gt;.
        Estimates are model-based associations and should not be interpreted as causal effects."
      )
    )
  )
)

# ============================================================
# SERVER
# ============================================================

server &lt;- function(input, output, session) {

  output$outcome_title &lt;- renderUI({
    div(
      class = "outcome-title",
      paste0(input$outcome, " transition")
    )
  })

  output$contexts &lt;- renderUI({

    panels &lt;- lapply(
      c("Low","Medium","High"),
      function(conc) {

        d &lt;- prob[
          prob$concentration == conc,
        ]

        cm &lt;- context_meta[
          context_meta$concentration == conc,
        ]

        div(
          class = "context-card",

          div(
            class = "context-head",
            div(
              class = "context-name",
              paste0(conc, " concentration")
            ),
            div(
              class = "context-range",
              paste0(cm$range, " non-native students")
            )
          ),

          div(
            class = "context-body",
            panel_svg(
              d,
              input$outcome
            )
          )
        )
      }
    )

    div(class = "contexts", panels)
  })

  output$reading &lt;- renderUI({

    meta &lt;- outcome_meta[[input$outcome]]

    get_gap &lt;- function(conc, gender) {
      d &lt;- prob[
        prob$concentration == conc &
        prob$gender == gender,
      ]
      100 * (
        d[d$background == "Native", meta$key] -
        d[d$background == "Non-native", meta$key]
      )
    }

    low_f &lt;- get_gap("Low","Female")
    high_f &lt;- get_gap("High","Female")
    low_m &lt;- get_gap("Low","Male")
    high_m &lt;- get_gap("High","Male")

    div(
      class = "reading",

      div(
        class = "reading-label",
        "Migrant-background gap"
      ),

      div(
        class = "reading-text",
        paste0(
          "For women, the Native–Non-native gap changes from ",
          sprintf("%.1f", abs(low_f)), " pp at low concentration to ",
          sprintf("%.1f", abs(high_f)), " pp at high concentration. ",
          "For men, it changes from ",
          sprintf("%.1f", abs(low_m)), " to ",
          sprintf("%.1f", abs(high_m)), " pp."
        )
      )
    )
  })
}

