}

svg_text &lt;- function(x, y, text, size = 12, colour = "#555555",
                     anchor = "start", weight = 400, class = NULL) {
  cls &lt;- if (is.null(class)) "" else paste0(' class="', class, '"')
  paste0(
    '&lt;text', cls,
    ' x="', x,
    '" y="', y,
    '" text-anchor="', anchor,
    '" font-size="', size,
    '" font-weight="', weight,
    '" fill="', colour,
    '" style="paint-order:stroke;stroke:white;stroke-width:4px;stroke-linejoin:round;"&gt;',
    esc(text),
    '&lt;/text&gt;'
  )
}

