  n = c(3695,2468,5014,1149,4012,2148,2026,2019,2019),
  transfer = c(16.2,21.5,19.3,13.9,19.5,16.1,25.0,17.5,12.9),
  outside = c(26.6,34.2,25.4,48.2,25.6,37.2,45.3,26.0,16.0),
  returned = c(3.0,3.8,3.2,3.8,3.3,3.3,4.9,3.0,2.0),
  complex = c(17.2,22.2,20.0,15.7,20.4,17.0,26.3,18.3,13.4),
  graduated = c(56.1,43.8,54.1,38.6,54.0,45.9,34.6,58.6,61.9),
  stringsAsFactors = FALSE
)

category_order &lt;- list(
  "Gender" = c("Female","Male"),
  "Age at entry" = c("Up to 21","22+"),
  "Working status" = c("Not working","Working"),
  "Entry grade" = c("Lower tertile","Middle tertile","Upper tertile")
)

state_col &lt;- c(
  university = "#5B8E7D",
  outside = "#D27A5E",
  graduated = "#667FB2"
)

group_palette &lt;- c("#3D78B2", "#D66B55", "#6E9B75")

year_labels &lt;- c("Entry","Y2","Y3","Y4","Y5","Y6")

# ============================================================
# Helpers
# ============================================================

state_legend &lt;- function(key, label) {
  div(
    class = "legend-item",
    span(
      class = "legend-swatch",
      style = paste0("background:", state_col[key], ";")
    ),
    label
  )
}

cohort_svg &lt;- function(d) {

  d &lt;- d[order(d$year), ]

  W &lt;- 430
  H &lt;- 235

  left &lt;- 42
  right &lt;- 18
  top &lt;- 18
  bottom &lt;- 40

  ph &lt;- H - top - bottom
  bar_gap &lt;- 5
  n &lt;- nrow(d)
  usable_w &lt;- W - left - right
  bar_w &lt;- (usable_w - bar_gap * (n - 1)) / n

  ymap &lt;- function(v) top + (100 - v) / 100 * ph

  svg &lt;- paste0(
    '&lt;svg viewBox="0 0 ',W,' ',H,
    '" style="width:100%;height:auto;display:block;"&gt;'
  )

  # horizontal grid and y-axis labels
  for (p in c(0,25,50,75,100)) {
    yy &lt;- ymap(p)
    svg &lt;- paste0(
      svg,
      '&lt;line x1="',left,'" y1="',yy,
      '" x2="',W-right,'" y2="',yy,
      '" stroke="#ededed" stroke-width="1"/&gt;',
      '&lt;text x="',left-8,'" y="',yy+3,
      '" text-anchor="end" font-size="8.5" fill="#8d8d8d"&gt;',
      p, '%&lt;/text&gt;'
    )
  }

  # TraMineR-style state distribution bars
  for (i in seq_len(n)) {

    x &lt;- left + (i - 1) * (bar_w + bar_gap)

    vals &lt;- c(
      university = d$university[i],
      outside = d$outside[i],
      graduated = d$graduated[i]
    )

    lower &lt;- 0

    for (k in c("university","outside","graduated")) {

      v &lt;- vals[k]
      y_top &lt;- ymap(lower + v)
      y_bottom &lt;- ymap(lower)
      h &lt;- y_bottom - y_top

      svg &lt;- paste0(
        svg,
        '&lt;rect x="',sprintf("%.2f",x),
        '" y="',sprintf("%.2f",y_top),
        '" width="',sprintf("%.2f",bar_w),
        '" height="',sprintf("%.2f",h),
        '" fill="',state_col[k],
        '" stroke="#555" stroke-width=".75"/&gt;'
      )

      # Add percentage labels only when the segment is large enough
      # to remain legible inside the stacked bar.
      if (v &gt;= 5) {

        label_y &lt;- y_top + h / 2
        label_col &lt;- "#FFFFFF"

        svg &lt;- paste0(
          svg,
          '&lt;text x="', sprintf("%.2f", x + bar_w / 2),
          '" y="', sprintf("%.2f", label_y + 3),
          '" text-anchor="middle" font-size="8.3" font-weight="650" fill="', label_col, '"&gt;',
          sprintf("%.1f%%", v),
          '&lt;/text&gt;'
        )
      }

      lower &lt;- lower + v
    }

    svg &lt;- paste0(
      svg,
      '&lt;text x="',sprintf("%.2f",x + bar_w/2),
      '" y="',H-14,
      '" text-anchor="middle" font-size="8.8" fill="#666"&gt;',
      year_labels[i], '&lt;/text&gt;'
    )
  }

  svg &lt;- paste0(
    svg,
    '&lt;line x1="',left,'" y1="',top,
    '" x2="',left,'" y2="',top+ph,
    '" stroke="#666" stroke-width="1"/&gt;',
    '&lt;line x1="',left,'" y1="',top+ph,
    '" x2="',W-right,'" y2="',top+ph,
    '" stroke="#666" stroke-width="1"/&gt;',
    '&lt;/svg&gt;'
  )

  HTML(svg)
}

cohort_card &lt;- function(d, category) {

  final &lt;- d[d$year == max(d$year), ]

  div(
    class = "group-card",

    div(
      class = "group-head",
      div(
        class = "group-title",
        category
      ),
      div(
        class = "group-n",
        paste0("n = ", format(final$n, big.mark=","))
      )
    ),

    div(
      class = "plot-wrap",
      cohort_svg(d)
    ),

    div(
      class = "final-row",

      div(
        class = "final-item",
        span(class="final-dot", style=paste0("background:",state_col["university"],";")),
        span(class="final-label","University"),
        strong(sprintf("%.1f%%",final$university))
      ),

      div(
        class = "final-item",
        span(class="final-dot", style=paste0("background:",state_col["outside"],";")),
        span(class="final-label","Outside"),
        strong(sprintf("%.1f%%",final$outside))
      ),

      div(
        class = "final-item",
        span(class="final-dot", style=paste0("background:",state_col["graduated"],";")),
        span(class="final-label","Graduated"),
        strong(sprintf("%.1f%%",final$graduated))
      )
    )
  )
}

metrics_svg &lt;- function(m) {

  cats &lt;- category_order[[unique(m$variable)]]
  m &lt;- m[match(cats, m$category), ]

  metrics &lt;- data.frame(
    key = c("transfer","outside","returned","complex","graduated"),
    label = c(
      "Ever transferred",
      "Ever outside university",
      "Returned after an exit",
      "2+ state changes",
      "Graduated at final observation"
    ),
    stringsAsFactors = FALSE
  )

  W &lt;- 860
  H &lt;- 355
  left &lt;- 215
  right &lt;- 55
  top &lt;- 42
  row_h &lt;- 57
  max_x &lt;- 65

  xmap &lt;- function(v) {
    left + (v/max_x) * (W-left-right)
  }

  svg &lt;- paste0(
    '&lt;svg viewBox="0 0 ',W,' ',H,
    '" style="width:100%;height:auto;display:block;"&gt;'
  )

  # axis
  for (p in c(0,20,40,60)) {
    xx &lt;- xmap(p)
    svg &lt;- paste0(
      svg,
      '&lt;line x1="',xx,'" y1="',top-11,
      '" x2="',xx,'" y2="',H-20,
      '" stroke="#eeeeee" stroke-width="1"/&gt;',
      '&lt;text x="',xx,'" y="',H-5,
      '" text-anchor="middle" font-size="9" fill="#999"&gt;',
      p, '%&lt;/text&gt;'
    )
  }

  # metric rows
  for (r in seq_len(nrow(metrics))) {

    cy &lt;- top + (r-1)*row_h

    svg &lt;- paste0(
      svg,
      '&lt;text x="8" y="',cy+4,
      '" font-size="11" font-weight="650" fill="#444"&gt;',
      metrics$label[r], '&lt;/text&gt;',

      '&lt;line x1="',left,'" y1="',cy,
      '" x2="',xmap(max_x),'" y2="',cy,
      '" stroke="#dddddd" stroke-width="2" stroke-linecap="round"/&gt;'
    )

    vals &lt;- m[[metrics$key[r]]]

    if (length(vals) &gt; 1) {
      svg &lt;- paste0(
        svg,
        '&lt;line x1="',min(xmap(vals)),'" y1="',cy,
        '" x2="',max(xmap(vals)),'" y2="',cy,
        '" stroke="#bdbdbd" stroke-width="4" stroke-linecap="round" opacity=".55"/&gt;'
      )
    }

    offsets &lt;- if (length(vals)==2) c(-7,7) else c(-10,0,10)

    for (i in seq_along(vals)) {

      xx &lt;- xmap(vals[i])
      yy &lt;- cy + offsets[i]

      svg &lt;- paste0(
        svg,
        '&lt;circle cx="',xx,'" cy="',yy,
        '" r="6.5" fill="',group_palette[i],
        '" stroke="#fff" stroke-width="1.5"/&gt;',

        '&lt;text x="',xx+10,'" y="',yy+4,
        '" font-size="9.5" font-weight="700" fill="#555"&gt;',
        sprintf("%.1f%%",vals[i]), '&lt;/text&gt;'
      )
    }
  }

  svg &lt;- paste0(svg, '&lt;/svg&gt;')
  HTML(svg)
}

group_legend &lt;- function(variable) {

  cats &lt;- category_order[[variable]]

  div(
    class = "group-legend",
    lapply(
      seq_along(cats),
      function(i) {
        div(
          class = "legend-item",
          span(
            class = "legend-dot",
            style = paste0("background:",group_palette[i],";")
          ),
          cats[i]
        )
      }
    )
  )
}

