# ============================================================
# SERVER
# ============================================================

server &lt;- function(input, output, session) {

  output$main_view &lt;- renderUI({

    req(input$compare_by)

    cats &lt;- category_order[[input$compare_by]]

    if (input$view == "cohort") {

      d &lt;- state_df[state_df$variable == input$compare_by, ]

      cards &lt;- lapply(
        cats,
        function(cat) {
          cohort_card(
            d[d$category == cat, ],
            cat
          )
        }
      )

      final &lt;- d[d$year == 6, ]

      grad_vals &lt;- final$graduated[match(cats, final$category)]
      out_vals &lt;- final$outside[match(cats, final$category)]

      hi_grad &lt;- cats[which.max(grad_vals)]
      lo_grad &lt;- cats[which.min(grad_vals)]
      grad_gap &lt;- max(grad_vals) - min(grad_vals)

      hi_out &lt;- cats[which.max(out_vals)]
      lo_out &lt;- cats[which.min(out_vals)]
      out_gap &lt;- max(out_vals) - min(out_vals)

      tagList(

        div(
          class = "section-head",

          div(
            div(class="section-title","Cohort over time"),
            div(
              class="section-copy",
              "Each panel follows the same cohort through six annual observations. Each vertical bar is one annual observation and sums to 100%. The coloured segments show the distribution of educational states over time, following the visual logic of a TraMineR state distribution plot."
            )
          ),

          div(
            class="state-legend",
            state_legend("university","University"),
            state_legend("outside","Not in university"),
            state_legend("graduated","Graduated")
          )
        ),

        div(
          class="group-grid",
          style=paste0(
            "grid-template-columns:repeat(",
            length(cats),
            ",minmax(0,1fr));"
          ),
          cards
        ),

        div(
          class="reading",
          div(class="reading-label","At final observation"),
          div(
            class="reading-text",
            paste0(
              hi_grad, " has the highest graduation share (",
              sprintf("%.1f",max(grad_vals)), "%), compared with ",
              lo_grad, " (", sprintf("%.1f",min(grad_vals)),
              "%): a ", sprintf("%.1f",grad_gap),
              "-point gap. The largest share outside university is observed for ",
              hi_out, " (", sprintf("%.1f",max(out_vals)),
              "%), versus ", lo_out, " (", sprintf("%.1f",min(out_vals)),
              "%)."
            )
          )
        )
      )

    } else {

      m &lt;- metrics_df[metrics_df$variable == input$compare_by, ]

      returned_vals &lt;- m$returned[match(cats,m$category)]
      trans_vals &lt;- m$transfer[match(cats,m$category)]
      comp_vals &lt;- m$complex[match(cats,m$category)]

      tagList(

        div(
          class="section-head",

          div(
            div(class="section-title","Pathway dynamics"),
            div(
              class="section-copy",
              "Instead of looking only at the final outcome, this view compares events that occur during the trajectory: transfers, exits, returns and repeated state changes."
            )
          ),

          group_legend(input$compare_by)
        ),

        div(
          class="dynamics-card",
          metrics_svg(m)
        ),

        div(
          class="definition-row",

          div(
            class="definition",
            HTML("&lt;strong&gt;Ever transferred&lt;/strong&gt;&lt;br&gt;At least one annual observation in the transfer state.")
          ),

          div(
            class="definition",
            HTML("&lt;strong&gt;Ever outside university&lt;/strong&gt;&lt;br&gt;At least one observed year outside university.")
          ),

          div(
            class="definition",
            HTML("&lt;strong&gt;Returned after an exit&lt;/strong&gt;&lt;br&gt;Re-enrolment after an observed year outside university.")
          ),

          div(
            class="definition",
            HTML("&lt;strong&gt;2+ state changes&lt;/strong&gt;&lt;br&gt;At least two changes between annual educational states.")
          )
        ),

        div(
          class="reading",
          div(class="reading-label","Complexity signal"),
          div(
            class="reading-text",
            paste0(
              "The largest transfer share is observed for ",
              cats[which.max(trans_vals)], " (",
              sprintf("%.1f",max(trans_vals)), "%). ",
              "The highest share with two or more state changes is ",
              cats[which.max(comp_vals)], " (",
              sprintf("%.1f",max(comp_vals)), "%). ",
              "Returns after an observed exit are comparatively uncommon in every group, ranging from ",
              sprintf("%.1f",min(returned_vals)), "% to ",
              sprintf("%.1f",max(returned_vals)), "%."
            )
          )
        )
      )
    }
  })
}

shinyApp(ui, server)
